    "artifacts/api-server/src/lib/logger.ts": "import pino from \"pino\";\n\nconst isProduction = process.env.NODE_ENV === \"production\";\n\nexport const logger = pino({\n  level: process.env.LOG_LEVEL ?? \"info\",\n  redact: [\n    \"req.headers.authorization\",\n    \"req.headers.cookie\",\n    \"res.headers['set-cookie']\",\n  ],\n  ...(isProduction\n    ? {}\n    : {\n        transport: {\n          target: \"pino-pretty\",\n          options: { colorize: true },\n        },\n      }),\n});\n",
    "artifacts/api-server/src/lib/provider-secrets.ts": "import { createCipheriv, createDecipheriv, hkdfSync, randomBytes } from \"node:crypto\";\n\nfunction encryptionKey(): Buffer {\n  const source = process.env.SESSION_SECRET;\n  if (!source) throw new Error(\"SESSION_SECRET is required to encrypt provider credentials.\");\n  return Buffer.from(\n    hkdfSync(\"sha256\", source, \"ai-router-provider-keys\", \"aes-256-gcm:v1\", 32),\n  );\n}\n\nexport function encryptProviderKey(value: string): string {\n  const nonce = randomBytes(12);\n  const cipher = createCipheriv(\"aes-256-gcm\", encryptionKey(), nonce);\n  const ciphertext = Buffer.concat([cipher.update(value, \"utf8\"), cipher.final()]);\n  const tag = cipher.getAuthTag();\n  return `v1.${nonce.toString(\"base64url\")}.${tag.toString(\"base64url\")}.${ciphertext.toString(\"base64url\")}`;\n}\n\nexport function decryptProviderKey(value: string): string {\n  const [version, noncePart, tagPart, ciphertextPart] = value.split(\".\");\n  if (version !== \"v1\" || !noncePart || !tagPart || !ciphertextPart) {\n    throw new Error(\"Provider credential has an unsupported encryption format.\");\n  }\n  const decipher = createDecipheriv(\n    \"aes-256-gcm\",\n    encryptionKey(),\n    Buffer.from(noncePart, \"base64url\"),\n  );\n  decipher.setAuthTag(Buffer.from(tagPart, \"base64url\"));\n  return Buffer.concat([\n    decipher.update(Buffer.from(ciphertextPart, \"base64url\")),\n    decipher.final(),\n  ]).toString(\"utf8\");\n}\n",
    "artifacts/api-server/src/lib/provider-url.ts": "import { lookup } from \"node:dns/promises\";\nimport { isIP } from \"node:net\";\n\nfunction publicIpv4(address: string): boolean {\n  const octets = address.split(\".\").map(Number);\n  if (octets.length !== 4 || octets.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) {\n    return false;\n  }\n  const [a, b] = octets;\n  if (a === 0 || a === 10 || a === 127 || a >= 224) return false;\n  if (a === 100 && b >= 64 && b <= 127) return false;\n  if (a === 169 && b === 254) return false;\n  if (a === 172 && b >= 16 && b <= 31) return false;\n  if (a === 192 && (b === 0 || b === 168)) return false;\n  if (a === 198 && (b === 18 || b === 19 || b === 51)) return false;\n  if (a === 203 && b === 0) return false;\n  return true;\n}\n\nfunction publicIpv6(address: string): boolean {\n  const normalized = address.toLowerCase().split(\"%\")[0];\n  if (!normalized || normalized === \"::\" || normalized === \"::1\") return false;\n  if (normalized.startsWith(\"::ffff:\")) {\n    const mapped = normalized.slice(7);\n    return isIP(mapped) === 4 && publicIpv4(mapped);\n  }\n  // Permit global unicast only. This excludes ULA, link-local, multicast,\n  // IPv4-compatible, and special-use ranges.\n  return normalized.startsWith(\"2\") || normalized.startsWith(\"3\");\n}\n\nfunction publicAddress(address: string): boolean {\n  return isIP(address) === 4\n    ? publicIpv4(address)\n    : isIP(address) === 6 && publicIpv6(address);\n}\n\nexport async function assertSafeProviderUrl(value: string): Promise<URL> {\n  let url: URL;\n  try {\n    url = new URL(value);\n  } catch {\n    throw new Error(\"Provider URL must be a valid HTTPS URL.\");\n  }\n  if (\n    url.protocol !== \"https:\" ||\n    url.username ||\n    url.password ||\n    (url.port !== \"\" && url.port !== \"443\") ||\n    !url.hostname ||\n    url.hostname.endsWith(\".localhost\") ||\n    url.hostname.endsWith(\".local\") ||\n    url.hostname.endsWith(\".internal\") ||\n    url.hostname === \"localhost\"\n  ) {\n    throw new Error(\"Provider URL must use HTTPS on a public host and standard port.\");\n  }\n  const addresses = isIP(url.hostname)\n    ? [{ address: url.hostname }]\n    : await lookup(url.hostname, { all: true, verbatim: true });\n  if (!addresses.length || addresses.some(({ address }) => !publicAddress(address))) {\n    throw new Error(\"Provider URL resolves to a private or reserved network address.\");\n  }\n  return url;\n}\n",
