    "lib/api-zod/src/generated/types/providerUpdate.ts": "/**\n * Generated by orval 🍺\n * Do not edit manually.\n * Api\n * AI Router Console and OpenAI-compatible model gateway API\n * OpenAPI spec version: 0.1.0\n */\n\nexport interface ProviderUpdate {\n  /**\n     * @minLength 1\n     * @maxLength 120\n     */\n  name?: string;\n  baseUrl?: string;\n  /**\n     * @maxLength 4096\n     * @nullable\n     */\n  apiKey?: string | null;\n  /**\n     * @minimum 1\n     * @maximum 1000\n     */\n  priority?: number;\n  /**\n     * @minimum 1000\n     * @maximum 120000\n     */\n  timeoutMs?: number;\n  enabled?: boolean;\n}\n",
