    "lib/api-zod/src/generated/types/routingSettings.ts": "/**\n * Generated by orval 🍺\n * Do not edit manually.\n * Api\n * AI Router Console and OpenAI-compatible model gateway API\n * OpenAPI spec version: 0.1.0\n */\nimport type { RoutingSettingsStrategy } from './routingSettingsStrategy';\n\nexport interface RoutingSettings {\n  strategy: RoutingSettingsStrategy;\n  markupPercent: number;\n  fallbackEnabled: boolean;\n}\n",
    "lib/api-zod/src/generated/types/routingSettingsInput.ts": "/**\n * Generated by orval 🍺\n * Do not edit manually.\n * Api\n * AI Router Console and OpenAI-compatible model gateway API\n * OpenAPI spec version: 0.1.0\n */\nimport type { RoutingSettingsInputStrategy } from './routingSettingsInputStrategy';\n\nexport interface RoutingSettingsInput {\n  strategy: RoutingSettingsInputStrategy;\n  /**\n     * @minimum 0\n     * @maximum 1000\n     */\n  markupPercent: number;\n  fallbackEnabled: boolean;\n}\n",
    "lib/api-zod/src/generated/types/routingSettingsInputStrategy.ts": "/**\n * Generated by orval 🍺\n * Do not edit manually.\n * Api\n * AI Router Console and OpenAI-compatible model gateway API\n * OpenAPI spec version: 0.1.0\n */\n\nexport type RoutingSettingsInputStrategy = typeof RoutingSettingsInputStrategy[keyof typeof RoutingSettingsInputStrategy];\n\n\nexport const RoutingSettingsInputStrategy = {\n  priority: 'priority',\n  lowest_cost: 'lowest_cost',\n  lowest_latency: 'lowest_latency',\n  round_robin: 'round_robin',\n  weighted: 'weighted',\n} as const;\n",
