  "components.json": "{\n  \"$schema\": \"https://ui.shadcn.com/schema.json\",\n  \"style\": \"new-york\",\n  \"rsc\": false,\n  \"tsx\": true,\n  \"tailwind\": {\n    \"css\": \"src/styles.css\",\n    \"baseColor\": \"slate\",\n    \"cssVariables\": true,\n    \"prefix\": \"\"\n  },\n  \"iconLibrary\": \"lucide\",\n  \"rtl\": false,\n  \"aliases\": {\n    \"components\": \"@/components\",\n    \"utils\": \"@/lib/utils\",\n    \"ui\": \"@/components/ui\",\n    \"lib\": \"@/lib\",\n    \"hooks\": \"@/hooks\"\n  },\n  \"registries\": {}\n}\n",
  "drizzle.config.ts": "import { defineConfig } from \"drizzle-kit\";\n\nexport default defineConfig({\n  dialect: \"postgresql\",\n  schema: \"./drizzle/schema.ts\",\n  out: \"./drizzle/migrations\",\n  dbCredentials: {\n    url: process.env.LOVABLE_DB_MIGRATION_URL ?? \"\",\n  },\n});\n",
  "drizzle/migrations/0000_create_vylonium_reservations.sql": "CREATE TABLE public.reservations (\n id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 80),\n phone text NOT NULL CHECK (phone ~ '^\\+?[0-9 ()-]{8,20}$'),\n visit_date date NOT NULL,\n visit_time time NOT NULL,\n guests integer NOT NULL CHECK (guests BETWEEN 1 AND 12),\n note text NOT NULL DEFAULT '' CHECK (char_length(note) <= 500),\n status text NOT NULL DEFAULT 'pending' CHECK (status = 'pending'),\n created_at timestamptz NOT NULL DEFAULT now()\n);\nGRANT INSERT ON public.reservations TO anon, authenticated;\nGRANT ALL ON public.reservations TO service_role;\nALTER TABLE public.reservations ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"Visitors can submit pending reservations\" ON public.reservations FOR INSERT TO anon, authenticated WITH CHECK (status = 'pending' AND visit_date >= (now() AT TIME ZONE 'Asia/Jakarta')::date AND visit_time >= '08:00'::time AND visit_time <= '21:00'::time);\nCOMMENT ON TABLE public.reservations IS 'Private reservation requests. No visitor read, update, or delete permissions.';",
